select case when orders.channel in ('store', 'mobile') then 'group_a' else 'other' end channel_group, count(distinct order_items.quantity) unique_orders from order_items right join orders on order_items.order_id = orders.id left join customers on customers.id = orders.customer_id group by case when orders.channel in ('store', 'mobile') then 'group_a' else 'other' end having count(distinct order_items.quantity) >= 1 order by channel_group asc, unique_orders desc;
